    z_t81_t* boxed = (z_t81_t*)z_xmalloc(sizeof(z_t81_t));
    boxed->data = start;
    boxed->size = remaining;
    s->cursor = s->src_len;
    s->done = true;
    out.tag = Z_T9603_TAG_1;
    out.data = boxed;
    return out;
